<?php
use Illuminate\Support\Facades\DB;use Modules\Core\Approval\ApprovalEngine;use Modules\Core\Models\ApprovalFlow;use Modules\Core\Models\ApprovalFlowStep;use Modules\Core\Models\Role;use Modules\Core\Models\User;use Modules\Cutting\Models\CustomerShadeRule;use Modules\Cutting\Services\CuttingService;use Modules\Cutting\Services\LayExecutionService;use Modules\MasterData\Models\ShadeGroup;use Modules\Production\Services\MaterialIssueService;use Modules\Receiving\Models\FabricRoll;
function layFixture():array{[$u,$fabric,,,$pcs,$warehouse,$mo,,,$cw,$size]=shopFixture();$rolls=FabricRoll::orderBy('id')->get();$sg1=ShadeGroup::create(['company_id'=>1,'code'=>'SG1-'.uniqid(),'name'=>'SG1']);$sg2=ShadeGroup::create(['company_id'=>1,'code'=>'SG2-'.uniqid(),'name'=>'SG2']);$rolls[0]->update(['shade_group_id'=>$sg1->id]);$rolls[1]->update(['shade_group_id'=>$sg2->id]);app(MaterialIssueService::class)->issue($mo,$warehouse->id,[['material_id'=>$fabric->id,'qty'=>200,'roll_id'=>$rolls[0]->id],['material_id'=>$fabric->id,'qty'=>100,'roll_id'=>$rolls[1]->id]],$u);$cut=app(CuttingService::class)->create($mo->fresh(),[['colorway_id'=>$cw->id,'size_id'=>$size->id,'qty_cut'=>100]],$u);return[$u,$cut,$rolls,$mo,$sg1,$sg2];}
it('defaults enabled, blocks NULL/different shade and accepts exact shade without ledger movement',function(){[$u,$cut,$rolls]=layFixture();$svc=app(LayExecutionService::class);$lay=$svc->createLay($cut,20,$u);expect($lay->shade_validation_enabled)->toBeTrue();$before=DB::table('stock_ledger')->count();$first=$svc->addRoll($lay,$rolls[0],80,$u);expect((float)$first->qty_used)->toBe(80.0);expect(fn()=>$svc->addRoll($lay->fresh(),$rolls[1],20,$u))->toThrow(RuntimeException::class,'BR-053 BLOCK');expect(DB::table('stock_ledger')->count())->toBe($before);});
it('buyer can disable shade blocking but quantity and cut-output lineage remain enforced',function(){[$u,$cut,$rolls]=layFixture();$customer=$cut->productionOrder->salesOrder->customer;CustomerShadeRule::create(['company_id'=>1,'customer_id'=>$customer->id,'enabled'=>false,'created_by'=>$u->id]);$svc=app(LayExecutionService::class);$lay=$svc->createLay($cut,10,$u);$svc->addRoll($lay,$rolls[0],50,$u);$svc->addRoll($lay->fresh(),$rolls[1],50,$u);$out=$svc->createOutput($lay->fresh(),$cut->lines->first()->id,100,$u);$bundles=$svc->generateBundles($out,20,$u);$done=$svc->completeLay($lay->fresh(),$u);expect($bundles)->toHaveCount(5)->and($bundles[0]->cutOutput->lay->rolls)->toHaveCount(2)->and($done->status)->toBe('COMPLETED');});
it('mismatch override remains blocked until ApprovalEngine approves',function(){[$u,$cut,$rolls]=layFixture();$role=Role::withoutGlobalScopes()->firstOrCreate(['company_id'=>1,'code'=>'cut_mgr'],['name'=>'Cut Manager']);$flow=ApprovalFlow::create(['company_id'=>1,'doc_type'=>'SHADE_OVERRIDE','version'=>1,'mode'=>'sequential','is_active'=>true]);ApprovalFlowStep::create(['flow_id'=>$flow->id,'step_no'=>1,'role_id'=>$role->id]);$approver=User::factory()->create(['company_id'=>1]);$approver->roles()->sync([$role->id]);$svc=app(LayExecutionService::class);$lay=$svc->createLay($cut,20,$u);$svc->addRoll($lay,$rolls[0],50,$u);$override=$svc->requestOverride($lay->fresh(),$rolls[1],25,'Buyer approved shade exception',$u);expect(fn()=>$svc->applyOverride($override,$u))->toThrow(RuntimeException::class,'ApprovalEngine APPROVED');app(ApprovalEngine::class)->approve($override->approvalRequest,$approver);$line=$svc->applyOverride($override->fresh(),$u);expect($line->shade_override)->toBeTrue()->and($line->fabric_roll_id)->toBe($rolls[1]->id);});
